#include "support/store_write_peer.h"
static void probe(xmqttversion V)
{
    jpdrive D={0};jpfile F=jpFile(&D);stsource Source;stSource(V,&Source);xmqttjournal* J=stWrite(F,V,Source.Ops,10,true);xmqttstorestateconfig C=stConfig(V);C.Delta.MaxOperations=1;C.Delta.Codec.MaxProperties=V==XMQTT_VERSION_5?4:0;xmqttstorestate* S=NULL;stStatus(xmqttStoreStateRecover(J,&C,&S),XMQTT_STORE_DONE,"measure actual cold peak");xmqttstorestateinfo Initial=stInfo(S);xmqttStoreStateDestroy(S);testRequire(xmqttJournalDestroy(J),"initial replay retired");xmqttjournalconfig JC=stJournalConfig(V);J=jpReopen(F,&JC);C.MaxMemoryBytes=Initial.PeakMemoryBytes;S=NULL;stStatus(xmqttStoreStateRecover(J,&C,&S),XMQTT_STORE_DONE,"same replay fits its exact peak budget");xmqttstorestateinfo Tight=stInfo(S);size_t Gap=C.MaxMemoryBytes-Tight.MemoryBytes;testRequire(Gap<512,"valid recovered model leaves less than metadata plan size");xtaskpool* Pool=jwPool(1);xmqttstorewriteconfig WC;xmqttStoreWriteConfigInit(&WC);xmqttstorewrite* W=(xmqttstorewrite*)(uintptr_t)1;WC.MaxScratchBytes=1024;testRequire(!xmqttStoreWriteCreate(Pool,J,S,&WC,&W)&&W==(xmqttstorewrite*)(uintptr_t)1&&stInfo(S).Inbox==2&&jpInfo(J).State==XMQTT_JOURNAL_READY,"insufficient worst-reset reserve refuses constructor and consumes neither source");xrtClearError();xmqttStoreWriteConfigInit(&WC);W=NULL;testRequire(xmqttStoreWriteCreate(Pool,J,S,&WC,&W),"writer accepts this valid recovered state");unsigned Calls=D.Calls;xmqttstoredelta Ack={.Type=XMQTT_STORE_INBOX_ACK,.Epoch=1,.Key=22};xfuture* Future=swOps(W,&C.Delta,&Ack,1);const xmqttcommitresult* R=jwOutcome(Future);xmqttstorewriteinfo Info=swInfo(W);
    printf("[PROGRESS] version%d replay_peak=%zu retained=%zu headroom=%zu status%d append%d before_calls%u after_calls%u inbox%zu\n",V,C.MaxMemoryBytes,Tight.MemoryBytes,Gap,R->Status,R->AppendCalled,Calls,D.Calls,Info.State.Inbox);
    testRequire(R->Status==XMQTT_COMMIT_OK&&R->AppendCalled&&D.Calls==Calls+7&&Info.State.Inbox==1&&Info.State.Transactions==Tight.Transactions+1&&Info.State.MemoryBytes<Tight.MemoryBytes&&!Info.Worker.Failed,"reserved metadata scratch lets delivery ACK free state at the exact valid recovered memory cap");xrtFutureDestroy(Future);testRequire(xmqttStoreWriteDestroy(W),"probe owner retired");jwPoolDone(Pool);jpFileClose(F);
}
int main(void){probe(XMQTT_VERSION_5);probe(XMQTT_VERSION_311);puts("[PASS] valid tight recovery budgets retain ACK progress and reject insufficient reset reserves before ownership transfer");return 0;}
